// osm-eink InkHUD per-zoom grid export: 50 tiles, zooms [13, 14, 15]
// Each tile is 256x256px = 8192 bytes uncompressed, stored here as raw LZ4 blocks.
// LZ4 uses high-compression mode in the exporter; the firmware decoder is unchanged.
// Byte layout is COLUMN-MAJOR: bytes are packed as [bx=0..31][y=0..255], not row-major.
// To read pixel (px, py): byte = tile[(px/8)*256 + py], bit = px%8
// map_tile_kinds: 0=LZ4 payload, 1=all-white tile, 2=all-black tile
// Identical compressed tiles are stored once and referenced by offset.
// unique payloads: 46 / 46 compressed tiles (0 deduplicated)
// sentinels: 4 white, 0 black
// Firmware: search map_tile_zooms/tx/ty for (zoom,tx,ty), then decompress
// map_tile_data + map_tile_offsets[i] using map_tile_sizes[i] bytes into an 8192-byte buffer,
// or synthesize a solid tile when map_tile_kinds[i] is a sentinel.
